interface Literal { kind: "literal"; value: number }
interface Binary  { kind: "binary"; left: Expr; op: string; right: Expr }  // named children
type Expr = Literal | Binary;

function print(e: Expr): string {
  switch (e.kind) {                                  // node-specific traversal
    case "literal": return String(e.value);
    case "binary":  return `(${print(e.left)} ${e.op} ${print(e.right)})`;
    default: return assertNever(e);                  // never-based exhaustiveness
  }
}
